#!/usr/bin/env bash\nset -e\n\n# Mock rationale: Verify that the Terraform module defines required resources without invoking AWS.\n\n# Check that main.tf contains aws_s3_bucket\nif ! grep -q 'resource "aws_s3_bucket" "safehouse"' src/main.tf; then\n  echo "Missing aws_s3_bucket resource"\n  exit 1\nfi\n\n# Check versioning\nif ! grep -q 'resource "aws_s3_bucket_versioning" "safehouse_versioning"' src/main.tf; then\n  echo "Missing versioning resource"\n  exit 1\nfi\n\n# Check encryption\nif ! grep -q 'resource "aws_s3_bucket_server_side_encryption_configuration" "safehouse_encryption"' src/main.tf; then\n  echo "Missing encryption resource"\n  exit 1\nfi\n\n# Check lifecycle\nif ! grep -q 'resource "aws_s3_bucket_lifecycle_configuration" "safehouse_lifecycle"' src/main.tf; then\n  echo "Missing lifecycle resource"\n  exit 1\nfi\n\n# Check IAM policy\nif ! grep -q 'resource "aws_iam_policy" "safehouse_readonly"' src/main.tf; then\n  echo "Missing IAM policy resource"\n  exit 1\nfi\n\necho "All checks passed."\n
